// §1.13 step 2 -- work out which object ids this run was asked to delete.
//
// The id may arrive at either of two levels depending on the caller, so both
// are read rather than assuming one shape. This is the same class of defect as
// the WF-002 envelope bug and the WF-003 `audio_features: $json` bug: a
// hand-off whose receiver expected a different shape than the sender sent, and
// which failed silently because nothing raised.
const item = $input.first().json || {};

const candidates = [
  item.audio_job_id,
  item.envelope?.body?.audio_job_id,
  item.envelope?.body?.audio?.audio_job_id,
  item.envelope?.recommendation_context?.audio_job_id,
];

const ids = [...new Set(candidates.filter((v) => typeof v === 'string' && v.length))];

return [{
  json: {
    request_id: item.request_id || '',
    requested_ids: ids,
    // Stated explicitly so the validation node downstream never has to guess
    // whether "no ids" meant "nothing to do" or "the lookup failed".
    source: ids.length ? 'explicit' : 'none',
  },
}];

// §1.13 step 3, and the section's hard rule: "Do not accept arbitrary client
// file paths."
//
// The rule is enforced by GRAMMAR, not by sanitising. An object id is exactly
// 32 lowercase hex characters -- 128 bits, server-generated, the same grammar
// audio-service's `storage.path_for` validates before it will touch the disk.
// Anything else is refused outright rather than cleaned up and passed along:
// `../../etc/passwd`, an absolute path, a URL, or a plausible-looking id with
// one stray character all fail the same way.
//
// Validating rather than sanitising is the deliberate choice. A sanitiser has
// to be right about every encoding trick; a grammar only has to be right about
// what a legitimate id looks like, and this one has exactly one shape.
const OBJECT_ID = /^[0-9a-f]{32}$/;

const data = $input.first().json;
const requested = Array.isArray(data.requested_ids) ? data.requested_ids : [];

const approved = [];
const rejected = [];

for (const id of requested) {
  if (OBJECT_ID.test(id)) {
    approved.push(id);
  } else {
    // The offending value is NOT echoed back. It is attacker-controlled text,
    // and reflecting it into a log or an error envelope is how a rejection
    // turns into a second vulnerability. Length and a hash-free description
    // are enough to debug with.
    rejected.push({ reason: 'does not match the approved object-id grammar', length: String(id).length });
  }
}

return [{
  json: {
    request_id: data.request_id || '',
    approved_ids: approved,
    rejected_count: rejected.length,
    rejections: rejected,
    // A run that was handed only invalid ids is a FAILURE, not a quiet no-op --
    // something upstream is constructing ids wrongly and should be reported.
    has_failure: rejected.length > 0,
    nothing_to_do: approved.length === 0 && rejected.length === 0,
  },
}];

// Classify the deletion.
//
// MEASURED, not assumed: audio-service answers DELETE with 200 for ANY
// well-formed id, including one that was never issued -- deliberately, so the
// endpoint cannot be used to test whether a given clip exists. Verified by
// deleting a fabricated id and getting 200 back.
//
// So a 404 branch here would be dead code, and `deleted` cannot mean "a file
// was removed". What it honestly means is the postcondition: THE STORE NO
// LONGER HOLDS THIS ID. That is the property cleanup actually owes, and it is
// true whether the clip was deleted just now or had already expired.
const res = $input.first().json || {};
const status = Number(res.statusCode || 0);
const approved = $('Validate Object Is Inside the Approved Temporary Store').first().json;
const objectId = (approved.approved_ids || [])[0] || '';

const deleted = status >= 200 && status < 300;
const failed = !deleted;

return [{
  json: {
    request_id: approved.request_id || '',
    object_id: objectId,
    status_code: status,
    deleted: deleted,
    has_failure: failed || approved.has_failure === true,
    failure_reason: failed ? `audio-service returned ${status}` : null,
    rejected_count: approved.rejected_count || 0,
  },
}];

const result = $('Interpret Deletion Result').first().json;
let marked = false;
try {
  const rows = $('Mark Job Cleaned').all();
  marked = rows.length > 0 && rows[0].json && rows[0].json.state === 'cleaned';
} catch (e) {
  // The cleanup record is secondary: the clip is already gone from disk, which
  // is the part that matters for privacy. A failed audit write is reported,
  // not escalated into a failed cleanup.
  marked = false;
}

return [{ json: { ...result, mode: 'explicit', marked_cleaned: marked } }];

// The scheduled branch's own result, in the same shape as the explicit branch
// so `Return Cleanup Result` does not need to know which trigger fired.
const res = $input.first().json || {};
const status = Number(res.statusCode || 0);
const body = res.body || {};
const ok = status >= 200 && status < 300;

return [{
  json: {
    request_id: '',
    mode: 'scheduled_sweep',
    removed: Number(body.removed || 0),
    stored_before: Number(body.stored_before || 0),
    stored_after: Number(body.stored_after || 0),
    retention_minutes: Number(body.retention_minutes || 0),
    status_code: status,
    has_failure: !ok,
    failure_reason: ok ? null : `audio-service sweep returned ${status}`,
  },
}];
